//! Native .NET 8 SDK generation for Kaji.
//!
//! The generator consumes Kaji's neutral [`Api`] model and emits an
//! implementation-independent C# client. Consumers provide their own
//! [`HttpClient`](https://learn.microsoft.com/dotnet/api/system.net.http.httpclient),
//! which keeps lifetime, proxies, retries, and observability in the host app.

use std::fmt::Write;

use anyhow::{Result, bail};
use kaji_core::{
    AdditionalProperties, Api, GeneratedFile, GeneratedTree, Operation, OperationResponse, Schema,
    SchemaKind, SchemaValue, SdkClientStyle,
};

const NOTICE: &str = "// <auto-generated />\n// Generated by Kaji. Do not edit.\n";

/// Generates an idiomatic .NET 8 C# SDK below `output_dir`.
///
/// The returned tree is intentionally not written to disk: a profile can
/// combine this output with other language targets before atomically
/// materializing it. `package_name` controls the NuGet package identity; when
/// omitted, a stable `<api>-sdk` name is derived from the API title.
pub fn generate_dotnet_sdk(
    api: &Api,
    output_dir: &str,
    package_name: Option<&str>,
) -> Result<GeneratedTree> {
    generate_dotnet_sdk_with_style(api, output_dir, package_name, SdkClientStyle::Flat)
}

/// Generates a .NET SDK with either a flat or resource-namespaced client.
///
/// [`SdkClientStyle::Flat`] preserves the original `KajiClient` API such as
/// `client.CreateContactAsync(...)`. [`SdkClientStyle::Namespaced`] additionally
/// exports resource properties, for example `client.Contacts.CreateAsync(...)`.
/// The direct methods remain available in both modes, so choosing the facade is
/// a non-breaking additive change for generated consumers.
pub fn generate_dotnet_sdk_with_style(
    api: &Api,
    output_dir: &str,
    package_name: Option<&str>,
    client_style: SdkClientStyle,
) -> Result<GeneratedTree> {
    let root = normalized_root(output_dir)?;
    let package = package_name
        .filter(|name| !name.trim().is_empty())
        .map(str::to_owned)
        .unwrap_or_else(|| format!("{}-sdk", kebab_case(&api.name)));
    let namespace = dotnet_namespace(&package);
    let project = format!("{}.csproj", pascal_case(&package));
    let mut tree = GeneratedTree::default();
    tree.insert(GeneratedFile::new(
        output_path(&root, &project),
        render_project(api, &package),
    )?)?;
    tree.insert(GeneratedFile::new(
        output_path(&root, "Models.cs"),
        render_models(api, &namespace),
    )?)?;
    tree.insert(GeneratedFile::new(
        output_path(&root, "ApiException.cs"),
        render_api_exception(api, &namespace),
    )?)?;
    tree.insert(GeneratedFile::new(
        output_path(&root, "KajiClient.cs"),
        render_client(api, &namespace, client_style),
    )?)?;
    if client_style == SdkClientStyle::Namespaced {
        tree.insert(GeneratedFile::new(
            output_path(&root, "Resources.cs"),
            render_resources(api, &namespace),
        )?)?;
    }
    tree.insert(GeneratedFile::new(
        output_path(&root, "README.md"),
        render_readme(api, &package, &namespace, client_style),
    )?)?;
    tree.insert(GeneratedFile::new(
        output_path(&root, "STYLE_GUIDE.md"),
        render_style_guide(api, &namespace, client_style),
    )?)?;
    Ok(tree)
}

fn normalized_root(output_dir: &str) -> Result<String> {
    let root = output_dir.trim_matches('/');
    if root.is_empty() {
        bail!(".NET SDK output directory cannot be empty");
    }
    if root.split('/').any(|component| component == "..") {
        bail!(".NET SDK output directory cannot contain parent-directory components");
    }
    Ok(root.to_owned())
}

fn output_path(root: &str, file: &str) -> String {
    format!("{root}/{file}")
}

fn render_project(api: &Api, package: &str) -> String {
    format!(
        "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <PropertyGroup>\n    <TargetFramework>net8.0</TargetFramework>\n    <ImplicitUsings>enable</ImplicitUsings>\n    <Nullable>enable</Nullable>\n    <LangVersion>latest</LangVersion>\n    <GeneratePackageOnBuild>false</GeneratePackageOnBuild>\n    <PackageId>{}</PackageId>\n    <Version>{}</Version>\n    <Description>Generated .NET client for {}</Description>\n  </PropertyGroup>\n</Project>\n",
        xml_escape(package),
        dotnet_version(&api.version),
        xml_escape(&api.name),
    )
}

fn render_models(api: &Api, namespace: &str) -> String {
    let mut output = format!(
        "{NOTICE}\nusing System.Text.Json;\nusing System.Text.Json.Serialization;\n\nnamespace {namespace};\n"
    );
    for schema in &api.schemas {
        output.push('\n');
        render_schema(&mut output, schema);
    }
    output
}

fn render_schema(output: &mut String, schema: &Schema) {
    let name = pascal_case(&schema.name);
    match &schema.value.kind {
        SchemaKind::Object {
            fields,
            additional_properties,
        } => {
            let _ = writeln!(output, "public sealed record {name}");
            output.push_str("{\n");
            for field in fields {
                let property = pascal_case(&field.name);
                let field_type = csharp_type(&field.value, !field.required);
                let required = if field.required && is_reference_type(&field.value) {
                    "required "
                } else {
                    ""
                };
                let _ = writeln!(
                    output,
                    "    [JsonPropertyName({:?})]\n    public {required}{field_type} {property} {{ get; init; }}",
                    field.name,
                );
            }
            if !matches!(additional_properties, AdditionalProperties::Forbidden) {
                output.push_str(
                    "    [JsonExtensionData]\n    public Dictionary<string, JsonElement>? AdditionalProperties { get; init; }\n",
                );
            }
            output.push_str("}\n");
        }
        SchemaKind::String if !schema.value.enum_values.is_empty() => {
            output.push_str("[JsonConverter(typeof(JsonStringEnumConverter))]\n");
            let _ = writeln!(output, "public enum {name}");
            output.push_str("{\n");
            for (index, value) in schema.value.enum_values.iter().enumerate() {
                let value = value.as_str().unwrap_or_default();
                let member = enum_member_name(value, index);
                let _ = writeln!(output, "    {member},");
            }
            output.push_str("}\n");
        }
        _ => {
            // C# has no public type aliases. A value record retains the named
            // schema in the generated API instead of silently erasing it.
            let value_type = csharp_type(&schema.value, false);
            let _ = writeln!(
                output,
                "public sealed record {name}([property: JsonPropertyName(\"value\")] {value_type} Value);"
            );
        }
    }
}

fn render_api_exception(api: &Api, namespace: &str) -> String {
    let mut output = format!(
        "{NOTICE}\nnamespace {namespace};\n\n/// <summary>An unsuccessful response returned by the API.</summary>\npublic class ApiException : Exception\n{{\n    public ApiException(int statusCode, string responseBody)\n        : base($\"API request failed with HTTP {{statusCode}}.\")\n    {{\n        StatusCode = statusCode;\n        ResponseBody = responseBody;\n    }}\n\n    public int StatusCode {{ get; }}\n\n    public string ResponseBody {{ get; }}\n}}\n"
    );
    for operation in &api.operations {
        for response in declared_error_responses(operation) {
            let error = dotnet_error_name(operation, response);
            let body = declared_error_type(response);
            let status = &response.status;
            if let Some(body) = body {
                let _ = writeln!(
                    output,
                    "\n/// <summary>Declared {status} response from {}.</summary>\npublic sealed class {error} : ApiException\n{{\n    public {error}(string responseBody, {body}? body) : base({status}, responseBody) => Body = body;\n    public {body}? Body {{ get; }}\n}}",
                    operation.id
                );
            } else {
                let _ = writeln!(
                    output,
                    "\n/// <summary>Declared {status} response from {}.</summary>\npublic sealed class {error} : ApiException\n{{\n    public {error}(string responseBody) : base({status}, responseBody) {{ }}\n}}",
                    operation.id
                );
            }
        }
    }
    output
}

fn render_client(api: &Api, namespace: &str, client_style: SdkClientStyle) -> String {
    let mut output = format!(
        "{NOTICE}\nusing System.Globalization;\nusing System.Net.Http.Json;\nusing System.Text;\nusing System.Text.Json;\nusing System.Text.Json.Serialization;\n\nnamespace {namespace};\n\n/// <summary>Configures a <see cref=\"KajiClient\"/> instance.</summary>\npublic sealed record KajiClientOptions\n{{\n    /// <summary>Absolute API base URL, for example <c>https://api.example.com</c>.</summary>\n    public required string BaseUrl {{ get; init; }}\n\n    public string? ApiKey {{ get; init; }}\n\n    public string ApiKeyHeader {{ get; init; }} = \"Authorization\";\n\n    /// <summary>Prefix sent before the API key, such as <c>Bearer</c>.</summary>\n    public string? ApiKeyPrefix {{ get; init; }} = \"Bearer\";\n}}\n\n/// <summary>Typed asynchronous client for {}.</summary>\npublic sealed class KajiClient\n{{\n    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web)\n    {{\n        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,\n    }};\n\n    private readonly HttpClient _httpClient;\n    private readonly Uri _baseUri;\n    private readonly string? _apiKey;\n    private readonly string _apiKeyHeader;\n    private readonly string? _apiKeyPrefix;\n\n    public KajiClient(HttpClient httpClient, KajiClientOptions options)\n    {{\n        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));\n        ArgumentNullException.ThrowIfNull(options);\n        _baseUri = new Uri(options.BaseUrl.TrimEnd('/') + \"/\", UriKind.Absolute);\n        _apiKey = options.ApiKey;\n        _apiKeyHeader = options.ApiKeyHeader;\n        _apiKeyPrefix = options.ApiKeyPrefix;\n    }}\n\n",
        xml_escape(&api.name),
    );
    // Keep the public options in the generated client file so packages remain
    // dependency-free, while making retry and lifecycle policy explicit.
    output = output.replacen(
        "using System.Net.Http.Json;",
        "using System.Net.Http.Headers;\nusing System.Net.Http.Json;",
        1,
    );
    output = output.replacen(
        "    public string? ApiKeyPrefix { get; init; } = \"Bearer\";\n}",
        "    public string? ApiKeyPrefix { get; init; } = \"Bearer\";\n\n    /// <summary>Null selects Kaji's safe three-attempt policy; set MaxAttempts to 1 to disable retries.</summary>\n    public KajiRetryOptions? Retry { get; init; }\n\n    public IKajiClientHooks? Hooks { get; init; }\n}\n\n/// <summary>Configures retries for idempotent requests.</summary>\npublic sealed record KajiRetryOptions\n{\n    public int MaxAttempts { get; init; } = 3;\n    public TimeSpan InitialDelay { get; init; } = TimeSpan.FromMilliseconds(250);\n    public TimeSpan MaxDelay { get; init; } = TimeSpan.FromSeconds(8);\n}\n\n/// <summary>Optional lifecycle callbacks for package telemetry and policy.</summary>\npublic interface IKajiClientHooks\n{\n    void BeforeRequest(HttpRequestMessage request) { }\n    void AfterResponse(HttpResponseMessage response) { }\n    void OnError(Exception error) { }\n}",
        1,
    );
    output = output.replacen(
        "    private readonly string? _apiKeyPrefix;\n",
        "    private readonly string? _apiKeyPrefix;\n    private readonly KajiRetryOptions _retry;\n    private readonly IKajiClientHooks? _hooks;\n",
        1,
    );
    output = output.replacen(
        "        _apiKeyPrefix = options.ApiKeyPrefix;\n    }",
        "        _apiKeyPrefix = options.ApiKeyPrefix;\n        _retry = options.Retry ?? new KajiRetryOptions();\n        if (_retry.MaxAttempts < 1) throw new ArgumentOutOfRangeException(nameof(options.Retry), \"MaxAttempts must be at least 1.\");\n        _hooks = options.Hooks;\n    }",
        1,
    );
    if client_style == SdkClientStyle::Namespaced {
        for group in operation_groups(api) {
            let resource = resource_name(&group);
            let _ = writeln!(
                output,
                "    /// <summary>Operations in the {group} resource.</summary>\n    public {resource}Resource {resource} {{ get; }}"
            );
        }
        output.push('\n');
        // The assignments must live in the constructor. Insert them after the
        // existing option assignments so all readonly properties are assigned.
        let assignments = operation_groups(api)
            .into_iter()
            .map(|group| {
                let resource = resource_name(&group);
                format!("        {resource} = new {resource}Resource(this);\n")
            })
            .collect::<String>();
        output = output.replacen(
            "        _hooks = options.Hooks;\n    }",
            &format!("        _hooks = options.Hooks;\n{assignments}    }}"),
            1,
        );
    }
    for operation in &api.operations {
        render_operation(&mut output, operation);
    }
    output.push_str(
        "    private HttpRequestMessage CreateRequest(HttpMethod method, string path, List<KeyValuePair<string, string?>>? query = null)\n    {\n        var uri = new Uri(_baseUri, path.TrimStart('/'));\n        if (query is { Count: > 0 })\n        {\n            var encoded = string.Join(\"&\", query\n                .Where(item => item.Value is not null)\n                .Select(item => $\"{Uri.EscapeDataString(item.Key)}={Uri.EscapeDataString(item.Value!)}\"));\n            if (!string.IsNullOrEmpty(encoded))\n            {\n                var builder = new UriBuilder(uri) { Query = encoded };\n                uri = builder.Uri;\n            }\n        }\n\n        var request = new HttpRequestMessage(method, uri);\n        request.Headers.Accept.ParseAdd(\"application/json\");\n        if (!string.IsNullOrWhiteSpace(_apiKey))\n        {\n            var credential = string.IsNullOrWhiteSpace(_apiKeyPrefix)\n                ? _apiKey\n                : $\"{_apiKeyPrefix} {_apiKey}\";\n            request.Headers.TryAddWithoutValidation(_apiKeyHeader, credential);\n        }\n        return request;\n    }\n\n    private async Task<T> SendAsync<T>(HttpRequestMessage request, CancellationToken cancellationToken)\n    {\n        using (request)\n        using var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);\n        var contents = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);\n        if (!response.IsSuccessStatusCode)\n        {\n            throw new ApiException((int)response.StatusCode, contents);\n        }\n        if (string.IsNullOrWhiteSpace(contents))\n        {\n            return default!;\n        }\n        return JsonSerializer.Deserialize<T>(contents, JsonOptions)\n            ?? throw new JsonException(\"Kaji received an empty JSON response.\");\n    }\n\n    private async Task SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)\n    {\n        using (request)\n        using var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);\n        var contents = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);\n        if (!response.IsSuccessStatusCode)\n        {\n            throw new ApiException((int)response.StatusCode, contents);\n        }\n    }\n\n    private static string ParameterString<T>(T value)\n    {\n        return value switch\n        {\n            null => string.Empty,\n            bool boolean => boolean ? \"true\" : \"false\",\n            IFormattable formattable => formattable.ToString(null, CultureInfo.InvariantCulture) ?? string.Empty,\n            _ => value.ToString() ?? string.Empty,\n        };\n    }\n}\n",
    );
    // The base template above closes KajiClient. The retry helpers are part of
    // that class, so reopen the tail before adding them and restore it below.
    debug_assert!(output.ends_with("}\n"));
    output.truncate(output.len() - 2);
    output.push_str(
        "\n    // The template request is cloned for every attempt: HttpRequestMessage instances\n    // are single-use, and replaying an unsafe POST would be incorrect.\n    private async Task<T> SendWithRetryAsync<T>(HttpRequestMessage template, CancellationToken cancellationToken)\n    {\n        using (template)\n        {\n            var maxAttempts = IsRetryAllowed(template) ? Math.Max(1, _retry.MaxAttempts) : 1;\n            Exception? transportError = null;\n            for (var attempt = 0; attempt < maxAttempts; attempt++)\n            {\n                using var request = await CloneRequestAsync(template, cancellationToken).ConfigureAwait(false);\n                try\n                {\n                    _hooks?.BeforeRequest(request);\n                    using var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);\n                    if (attempt + 1 < maxAttempts && IsRetryable(response.StatusCode))\n                    {\n                        await DelayForRetryAsync(attempt, response.Headers.RetryAfter, cancellationToken).ConfigureAwait(false);\n                        continue;\n                    }\n                    var contents = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);\n                    if (!response.IsSuccessStatusCode)\n                    {\n                        var error = new ApiException((int)response.StatusCode, contents);\n                        _hooks?.OnError(error);\n                        throw error;\n                    }\n                    _hooks?.AfterResponse(response);\n                    if (string.IsNullOrWhiteSpace(contents)) return default!;\n                    return JsonSerializer.Deserialize<T>(contents, JsonOptions)\n                        ?? throw new JsonException(\"Kaji received an empty JSON response.\");\n                }\n                catch (HttpRequestException error) when (attempt + 1 < maxAttempts)\n                {\n                    transportError = error;\n                    await DelayForRetryAsync(attempt, null, cancellationToken).ConfigureAwait(false);\n                }\n                catch (Exception error)\n                {\n                    _hooks?.OnError(error);\n                    throw;\n                }\n            }\n            _hooks?.OnError(transportError ?? new HttpRequestException(\"Kaji retry loop completed without a response.\"));\n            throw transportError ?? new HttpRequestException(\"Kaji retry loop completed without a response.\");\n        }\n    }\n\n    private async Task SendWithRetryAsync(HttpRequestMessage template, CancellationToken cancellationToken)\n    {\n        await SendWithRetryAsync<JsonElement>(template, cancellationToken).ConfigureAwait(false);\n    }\n\n    private static bool IsRetryAllowed(HttpRequestMessage request)\n    {\n        return request.Method == HttpMethod.Get || request.Method == HttpMethod.Put || request.Method == HttpMethod.Patch || request.Method == HttpMethod.Delete\n            || (request.Method == HttpMethod.Post && request.Headers.Contains(\"Idempotency-Key\"));\n    }\n\n    private static bool IsRetryable(HttpStatusCode status)\n    {\n        return status is HttpStatusCode.RequestTimeout or (HttpStatusCode)429 or HttpStatusCode.InternalServerError or HttpStatusCode.BadGateway or HttpStatusCode.ServiceUnavailable or HttpStatusCode.GatewayTimeout;\n    }\n\n    private async Task DelayForRetryAsync(int attempt, RetryConditionHeaderValue? retryAfter, CancellationToken cancellationToken)\n    {\n        var delay = retryAfter?.Delta ?? (retryAfter?.Date is { } date ? date - DateTimeOffset.UtcNow : TimeSpan.Zero);\n        if (delay <= TimeSpan.Zero)\n        {\n            var multiplier = Math.Pow(2, attempt);\n            delay = TimeSpan.FromMilliseconds(_retry.InitialDelay.TotalMilliseconds * multiplier);\n        }\n        delay = delay > _retry.MaxDelay ? _retry.MaxDelay : delay;\n        if (delay > TimeSpan.Zero) await Task.Delay(delay, cancellationToken).ConfigureAwait(false);\n    }\n\n    private static async Task<HttpRequestMessage> CloneRequestAsync(HttpRequestMessage source, CancellationToken cancellationToken)\n    {\n        var clone = new HttpRequestMessage(source.Method, source.RequestUri);\n        foreach (var header in source.Headers) clone.Headers.TryAddWithoutValidation(header.Key, header.Value);\n        if (source.Content is not null)\n        {\n            var bytes = await source.Content.ReadAsByteArrayAsync(cancellationToken).ConfigureAwait(false);\n            clone.Content = new ByteArrayContent(bytes);\n            foreach (var header in source.Content.Headers) clone.Content.Headers.TryAddWithoutValidation(header.Key, header.Value);\n        }\n        return clone;\n    }\n",
    );
    output = output.replacen(
        "                        var error = new ApiException((int)response.StatusCode, contents);\n                        _hooks?.OnError(error);\n                        throw error;",
        "                        throw new ApiException((int)response.StatusCode, contents);",
        1,
    );
    output.push_str(
        "\n    /// <summary>Downloads a non-JSON representation without attempting JSON deserialization.</summary>\n    private async Task<byte[]> SendBytesAsync(HttpRequestMessage request, CancellationToken cancellationToken)\n    {\n        using (request)\n        using var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);\n        var bytes = await response.Content.ReadAsByteArrayAsync(cancellationToken).ConfigureAwait(false);\n        if (!response.IsSuccessStatusCode)\n        {\n            var error = new ApiException((int)response.StatusCode, Encoding.UTF8.GetString(bytes));\n            _hooks?.OnError(error);\n            throw error;\n        }\n        _hooks?.AfterResponse(response);\n        return bytes;\n    }\n\n    /// <summary>Yields payloads from an OpenAPI text/event-stream response. The underlying response is disposed when enumeration ends.</summary>\n    private async IAsyncEnumerable<string> StreamSseAsync(HttpRequestMessage request, [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken cancellationToken)\n    {\n        using (request)\n        using var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);\n        if (!response.IsSuccessStatusCode)\n        {\n            var body = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);\n            var error = new ApiException((int)response.StatusCode, body);\n            _hooks?.OnError(error);\n            throw error;\n        }\n        _hooks?.AfterResponse(response);\n        await using var stream = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);\n        using var reader = new StreamReader(stream);\n        while (!reader.EndOfStream)\n        {\n            var line = await reader.ReadLineAsync(cancellationToken).ConfigureAwait(false);\n            if (string.IsNullOrEmpty(line) || line.StartsWith(\":\", StringComparison.Ordinal)) continue;\n            yield return line.StartsWith(\"data:\", StringComparison.Ordinal) ? line[5..].TrimStart() : line;\n        }\n    }\n"
    );
    render_declared_error_mappers(&mut output, api);
    output.push_str("\n    // Limited JSONPath evaluator for declared cursor output paths. It accepts only $.field.nestedField; unsupported expressions stop the pager rather than guessing.\n    private static string? KajiJsonPath(JsonElement value, string path)\n    {\n        if (!path.StartsWith('$')) return null;\n        var current = value;\n        foreach (var segment in path[1..].Split('.', StringSplitOptions.RemoveEmptyEntries))\n        {\n            if (current.ValueKind != JsonValueKind.Object || !current.TryGetProperty(segment, out current)) return null;\n        }\n        return current.ValueKind == JsonValueKind.String ? current.GetString() : null;\n    }\n");
    output.push_str("}\n");
    output
}

fn render_operation(output: &mut String, operation: &Operation) {
    let name = pascal_case(&operation.id);
    let response = operation_response_surface(operation);
    let mut required_parameters = Vec::new();
    let mut optional_parameters = Vec::new();
    for parameter in &operation.parameters {
        let parameter_name = camel_case(&parameter.name);
        let parameter_type = parameter
            .schema
            .as_ref()
            .map(|schema| csharp_type(schema, !parameter.required))
            .unwrap_or_else(|| "JsonElement".into());
        if parameter.required {
            required_parameters.push(format!("{parameter_type} {parameter_name}"));
        } else {
            optional_parameters.push(format!("{parameter_type} {parameter_name} = default"));
        }
    }
    let binary_body = request_body_is_binary(operation);
    let body = operation_request_type(operation)
        .map(|body| if binary_body { "byte[]".into() } else { body });
    if let Some(body_type) = &body {
        let required = operation
            .request_body
            .as_ref()
            .is_none_or(|body| body.required);
        let body_type = nullable_type(body_type.clone(), !required);
        if required {
            required_parameters.push(format!("{body_type} body"));
        } else {
            optional_parameters.push(format!("{body_type} body = default"));
        }
    }
    let mut parameters = required_parameters;
    parameters.extend(optional_parameters);
    parameters.push("CancellationToken cancellationToken = default".into());
    let return_type = match &response {
        DotnetResponseSurface::Json(value) => format!("Task<{value}>"),
        DotnetResponseSurface::Binary => "Task<byte[]>".into(),
        DotnetResponseSurface::Sse => "IAsyncEnumerable<string>".into(),
        DotnetResponseSurface::Empty => "Task".into(),
    };
    let declaration = if matches!(response, DotnetResponseSurface::Sse) {
        "async IAsyncEnumerable<string>".to_owned()
    } else {
        format!("async {return_type}")
    };
    let _ = writeln!(
        output,
        "    /// <summary>Invokes {} {}.</summary>\n    public {} {name}Async({})\n    {{",
        operation.method.as_str(),
        xml_escape(&operation.path),
        declaration,
        parameters.join(", "),
    );
    let _ = writeln!(output, "        var path = {:?};", operation.path);
    for parameter in operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "path")
    {
        let name = camel_case(&parameter.name);
        let _ = writeln!(
            output,
            "        path = path.Replace({:?}, Uri.EscapeDataString(ParameterString({name})), StringComparison.Ordinal);",
            format!("{{{}}}", parameter.name),
        );
    }
    output.push_str("        var query = new List<KeyValuePair<string, string?>>();\n");
    for parameter in operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "query")
    {
        let name = camel_case(&parameter.name);
        let _ = writeln!(
            output,
            "        query.Add(new KeyValuePair<string, string?>({:?}, {name} is null ? null : ParameterString({name})));",
            parameter.name,
        );
    }
    let _ = writeln!(
        output,
        "        var request = CreateRequest(HttpMethod.{}, path, query);",
        http_method_name(operation.method.as_str()),
    );
    for parameter in operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "header")
    {
        let name = camel_case(&parameter.name);
        let _ = writeln!(
            output,
            "        if ({name} is not null) request.Headers.TryAddWithoutValidation({:?}, ParameterString({name}));",
            parameter.name,
        );
    }
    if body.is_some() {
        if binary_body {
            output.push_str("        if (body is not null)\n        {\n            request.Content = new ByteArrayContent(body);\n            request.Content.Headers.ContentType = new MediaTypeHeaderValue(\"application/octet-stream\");\n        }\n");
        } else {
            output.push_str("        if (body is not null)\n        {\n            request.Content = JsonContent.Create(body, options: JsonOptions);\n        }\n");
        }
    }
    // C# iterators cannot yield from a try/catch block. SSE errors stay as the
    // common ApiException for now; normal request methods get status mapping.
    let maps_declared_errors = !declared_error_responses(operation).is_empty()
        && !matches!(response, DotnetResponseSurface::Sse);
    if maps_declared_errors {
        output.push_str("        try\n        {\n");
    }
    match response {
        DotnetResponseSurface::Json(response) => {
            let _ = writeln!(
                output,
                "        return await SendWithRetryAsync<{response}>(request, cancellationToken).ConfigureAwait(false);"
            );
        }
        DotnetResponseSurface::Binary => output.push_str(
            "        return await SendBytesAsync(request, cancellationToken).ConfigureAwait(false);\n",
        ),
        DotnetResponseSurface::Sse => output.push_str(
            "        await foreach (var item in StreamSseAsync(request, cancellationToken).ConfigureAwait(false))\n        {\n            yield return item;\n        }\n",
        ),
        DotnetResponseSurface::Empty => output.push_str(
            "        await SendWithRetryAsync(request, cancellationToken).ConfigureAwait(false);\n",
        ),
    }
    if maps_declared_errors {
        let map = dotnet_error_mapper_name(operation);
        let _ = writeln!(
            output,
            "        }}\n        catch (ApiException error)\n        {{\n            throw {map}(error);\n        }}"
        );
    } else {
        output.push_str("        }\n");
    }
    output.push_str("    }\n\n");
    if let Some(next_cursor_path) = dotnet_cursor_pagination(operation) {
        render_cursor_pager(output, operation, &next_cursor_path);
    }
}

fn dotnet_cursor_pagination(operation: &Operation) -> Option<String> {
    let extension = operation
        .annotations
        .get("x-kaji-pagination")
        .or_else(|| operation.annotations.get("x-speakeasy-pagination"))?
        .as_object()?;
    if extension.get("type")?.as_str()? != "cursor"
        || !matches!(
            operation_response_surface(operation),
            DotnetResponseSurface::Json(_)
        )
    {
        return None;
    }
    let input =
        extension.get("inputs")?.as_array()?.iter().find(|input| {
            input.get("type").and_then(serde_json::Value::as_str) == Some("cursor")
        })?;
    let name = input.get("name")?.as_str()?;
    let parameter = operation.parameters.iter().find(|parameter| {
        parameter.name == name
            && matches!(parameter.location.as_str(), "query" | "header" | "path")
            && (parameter.location != "path" || parameter.required)
    })?;
    if !matches!(parameter.schema.as_ref()?.kind, SchemaKind::String) {
        return None;
    }
    extension
        .get("outputs")?
        .get("nextCursor")?
        .as_str()
        .map(str::to_owned)
}

fn render_cursor_pager(output: &mut String, operation: &Operation, next_cursor_path: &str) {
    let name = pascal_case(&operation.id);
    let DotnetResponseSurface::Json(response) = operation_response_surface(operation) else {
        return;
    };
    let cursor_name = operation
        .annotations
        .get("x-kaji-pagination")
        .or_else(|| operation.annotations.get("x-speakeasy-pagination"))
        .and_then(serde_json::Value::as_object)
        .and_then(|extension| extension.get("inputs"))
        .and_then(serde_json::Value::as_array)
        .and_then(|inputs| {
            inputs.iter().find(|input| {
                input.get("type").and_then(serde_json::Value::as_str) == Some("cursor")
            })
        })
        .and_then(|input| input.get("name"))
        .and_then(serde_json::Value::as_str)
        .map(camel_case)
        .expect("validated cursor pagination");
    let parameters = facade_parameters(operation);
    let mut arguments = facade_arguments(operation);
    if let Some(argument) = arguments
        .iter_mut()
        .find(|argument| *argument == &cursor_name)
    {
        *argument = "currentCursor".into();
    }
    let operation_id = &operation.id;
    let parameters = parameters[..parameters.len() - 1].join(", ");
    let arguments = arguments.join(", ");
    let _ = writeln!(
        output,
        "    /// <summary>Lazily follows the declared cursor pagination contract for {operation_id}.</summary>\n    public async IAsyncEnumerable<{response}> {name}PagesAsync({parameters}, [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken cancellationToken = default)\n    {{\n        var currentCursor = {cursor_name};\n        while (true)\n        {{\n            var page = await {name}Async({arguments}).ConfigureAwait(false);\n            yield return page;\n            var nextCursor = KajiJsonPath(JsonSerializer.SerializeToElement(page, JsonOptions), {next_cursor_path:?});\n            if (string.IsNullOrEmpty(nextCursor)) yield break;\n            currentCursor = nextCursor;\n        }}\n    }}\n"
    );
}

/// Emits error selection at the operation boundary, after the common transport
/// has retained the status and raw payload. Only concrete non-2xx statuses are
/// mapped: an OpenAPI `default` response has no stable status-specific class.
fn render_declared_error_mappers(output: &mut String, api: &Api) {
    for operation in &api.operations {
        let responses = declared_error_responses(operation);
        if responses.is_empty() {
            continue;
        }
        let mapper = dotnet_error_mapper_name(operation);
        let _ = writeln!(
            output,
            "\n    private static ApiException {mapper}(ApiException error)\n    {{\n        switch (error.StatusCode)\n        {{"
        );
        for response in responses {
            let status = &response.status;
            let error_name = dotnet_error_name(operation, response);
            if let Some(body) = declared_error_type(response) {
                let _ = writeln!(
                    output,
                    "            case {status}: return new {error_name}(error.ResponseBody, TryDeserializeError<{body}>(error.ResponseBody));"
                );
            } else {
                let _ = writeln!(
                    output,
                    "            case {status}: return new {error_name}(error.ResponseBody);"
                );
            }
        }
        output.push_str("            default: return error;\n        }\n    }\n");
    }
    output.push_str("\n    private static T? TryDeserializeError<T>(string contents)\n    {\n        if (string.IsNullOrWhiteSpace(contents)) return default;\n        try { return JsonSerializer.Deserialize<T>(contents, JsonOptions); }\n        catch (JsonException) { return default; }\n    }\n");
}

fn declared_error_responses(operation: &Operation) -> Vec<&OperationResponse> {
    operation
        .responses
        .iter()
        .filter(|response| {
            response
                .status
                .parse::<u16>()
                .is_ok_and(|status| !(200..300).contains(&status))
        })
        .collect()
}

fn declared_error_type(response: &OperationResponse) -> Option<String> {
    response
        .media_types
        .iter()
        .find(|media| is_json_media(&media.content_type))
        .and_then(|media| media.schema.as_ref())
        .map(|schema| csharp_type(schema, false))
}

fn dotnet_error_name(operation: &Operation, response: &OperationResponse) -> String {
    format!(
        "{}Status{}Exception",
        pascal_case(&operation.id),
        response.status
    )
}

fn dotnet_error_mapper_name(operation: &Operation) -> String {
    format!("Map{}Error", pascal_case(&operation.id))
}

fn render_resources(api: &Api, namespace: &str) -> String {
    let mut output = format!(
        "{NOTICE}\nnamespace {namespace};\n\n// Resource facades delegate to KajiClient so configuration stays centralized.\n"
    );
    for resource in operation_groups(api) {
        let _ = writeln!(
            output,
            "\n/// <summary>Typed operations for the {resource} resource.</summary>\npublic sealed class {resource}Resource\n{{\n    private readonly KajiClient _client;\n\n    internal {resource}Resource(KajiClient client) => _client = client;\n"
        );
        for operation in api
            .operations
            .iter()
            .filter(|operation| operation_resource_name(operation) == resource)
        {
            render_resource_operation(&mut output, operation);
        }
        output.push_str("}\n");
    }
    output
}

fn render_resource_operation(output: &mut String, operation: &Operation) {
    let name = pascal_case(&operation.id);
    let return_type = match operation_response_surface(operation) {
        DotnetResponseSurface::Json(value) => format!("Task<{value}>"),
        DotnetResponseSurface::Binary => "Task<byte[]>".into(),
        DotnetResponseSurface::Sse => "IAsyncEnumerable<string>".into(),
        DotnetResponseSurface::Empty => "Task".into(),
    };
    let parameters = facade_parameters(operation);
    let arguments = facade_arguments(operation);
    let _ = writeln!(
        output,
        "    /// <summary>Invokes {} {}.</summary>\n    public {return_type} {name}Async({}) => _client.{name}Async({});\n",
        operation.method.as_str(),
        xml_escape(&operation.path),
        parameters.join(", "),
        arguments.join(", "),
    );
}

/// The generated direct client intentionally orders required parameters before
/// optional ones. Facades use the same order and defaults so the delegation is
/// a transparent, strongly typed forwarding call.
fn facade_parameters(operation: &Operation) -> Vec<String> {
    let mut required = Vec::new();
    let mut optional = Vec::new();
    for parameter in &operation.parameters {
        let declaration = format!(
            "{} {}{}",
            parameter
                .schema
                .as_ref()
                .map(|schema| csharp_type(schema, !parameter.required))
                .unwrap_or_else(|| "JsonElement".into()),
            camel_case(&parameter.name),
            if parameter.required { "" } else { " = default" },
        );
        if parameter.required {
            required.push(declaration);
        } else {
            optional.push(declaration);
        }
    }
    if let Some(body_type) = operation_request_type(operation) {
        let required_body = operation
            .request_body
            .as_ref()
            .is_none_or(|body| body.required);
        let declaration = format!(
            "{} body{}",
            nullable_type(
                if request_body_is_binary(operation) {
                    "byte[]".into()
                } else {
                    body_type
                },
                !required_body
            ),
            if required_body { "" } else { " = default" },
        );
        if required_body {
            required.push(declaration);
        } else {
            optional.push(declaration);
        }
    }
    required.extend(optional);
    required.push("CancellationToken cancellationToken = default".into());
    required
}

fn facade_arguments(operation: &Operation) -> Vec<String> {
    let mut required = Vec::new();
    let mut optional = Vec::new();
    for parameter in &operation.parameters {
        let name = camel_case(&parameter.name);
        if parameter.required {
            required.push(name);
        } else {
            optional.push(name);
        }
    }
    if operation_request_type(operation).is_some() {
        let required_body = operation
            .request_body
            .as_ref()
            .is_none_or(|body| body.required);
        if required_body {
            required.push("body".into());
        } else {
            optional.push("body".into());
        }
    }
    required.extend(optional);
    required.push("cancellationToken".into());
    required
}

fn operation_groups(api: &Api) -> Vec<String> {
    let mut groups = api
        .operations
        .iter()
        .map(operation_resource_name)
        .collect::<Vec<_>>();
    groups.sort();
    groups.dedup();
    groups
}

fn operation_resource_name(operation: &Operation) -> String {
    let tag = operation
        .annotations
        .get("tags")
        .and_then(serde_json::Value::as_array)
        .and_then(|tags| tags.first())
        .and_then(serde_json::Value::as_str)
        .or_else(|| {
            operation
                .annotations
                .get("tag")
                .and_then(serde_json::Value::as_str)
        });
    tag.map(resource_name)
        .unwrap_or_else(|| resource_name(&path_resource_segment(&operation.path)))
}

fn path_resource_segment(path: &str) -> String {
    path.split('/')
        .filter(|segment| !segment.is_empty() && !segment.starts_with('{'))
        .find(|segment| {
            let lowered = segment.to_ascii_lowercase();
            lowered != "api"
                && lowered != "email"
                && !(lowered.starts_with('v')
                    && lowered.len() > 1
                    && lowered[1..]
                        .chars()
                        .all(|character| character.is_ascii_digit()))
        })
        .unwrap_or("default")
        .into()
}

fn resource_name(value: &str) -> String {
    let name = pascal_case(value);
    if name == "GeneratedValue" {
        "Default".into()
    } else {
        name
    }
}

enum DotnetResponseSurface {
    Json(String),
    Binary,
    Sse,
    Empty,
}

fn is_json_media(content_type: &str) -> bool {
    content_type.contains("json") || content_type.ends_with("+json")
}

fn is_sse_media(content_type: &str) -> bool {
    content_type.eq_ignore_ascii_case("text/event-stream")
}

fn request_body_is_binary(operation: &Operation) -> bool {
    operation.request_body.as_ref().is_some_and(|body| {
        body.media_types
            .iter()
            .find(|media| is_json_media(&media.content_type))
            .or_else(|| body.media_types.first())
            .is_some_and(|media| !is_json_media(&media.content_type))
    })
}

fn operation_response_surface(operation: &Operation) -> DotnetResponseSurface {
    operation
        .responses
        .iter()
        .find(|response| response.status.starts_with('2'))
        .or_else(|| {
            operation
                .responses
                .iter()
                .find(|response| response.status == "default")
        })
        .and_then(|response| {
            response
                .media_types
                .iter()
                .find(|media| is_sse_media(&media.content_type))
                .or_else(|| {
                    response
                        .media_types
                        .iter()
                        .find(|media| is_json_media(&media.content_type))
                })
                .or_else(|| response.media_types.first())
        })
        .map(|media| {
            if is_sse_media(&media.content_type) {
                DotnetResponseSurface::Sse
            } else if is_json_media(&media.content_type) {
                media
                    .schema
                    .as_ref()
                    .map(|schema| DotnetResponseSurface::Json(csharp_type(schema, false)))
                    .unwrap_or(DotnetResponseSurface::Empty)
            } else {
                DotnetResponseSurface::Binary
            }
        })
        .unwrap_or_else(
            || match operation.response_type.to_ascii_lowercase().as_str() {
                "" | "void" | "nil" | "null" => DotnetResponseSurface::Empty,
                _ => DotnetResponseSurface::Json(csharp_type_name(&operation.response_type, false)),
            },
        )
}

fn operation_request_type(operation: &Operation) -> Option<String> {
    operation
        .request_body
        .as_ref()
        .and_then(|body| {
            body.media_types
                .iter()
                .find(|media| media.content_type.contains("json"))
                .or_else(|| body.media_types.first())
        })
        .and_then(|media| media.schema.as_ref())
        .map(|schema| csharp_type(schema, false))
        .or_else(|| {
            operation
                .request_type
                .as_ref()
                .map(|value| csharp_type_name(value, false))
        })
}

fn csharp_type_name(value: &str, nullable: bool) -> String {
    let base = match value.to_ascii_lowercase().as_str() {
        "any" | "unknown" | "object" | "null" => "JsonElement".into(),
        "boolean" | "bool" => "bool".into(),
        "integer" | "int" | "int32" => "int".into(),
        "int64" => "long".into(),
        "number" | "float" | "float64" => "double".into(),
        "string" => "string".into(),
        "array" => "List<JsonElement>".into(),
        _ => pascal_case(value),
    };
    nullable_type(base, nullable)
}

fn csharp_type(value: &SchemaValue, optional: bool) -> String {
    let base = match &value.kind {
        SchemaKind::Any | SchemaKind::Null | SchemaKind::Not { .. } => "JsonElement".into(),
        SchemaKind::Boolean => "bool".into(),
        SchemaKind::Integer => match value.format.as_deref() {
            Some("int32") => "int".into(),
            _ => "long".into(),
        },
        SchemaKind::Number => match value.format.as_deref() {
            Some("float") | Some("float32") => "float".into(),
            Some("decimal") => "decimal".into(),
            _ => "double".into(),
        },
        SchemaKind::String => match value.format.as_deref() {
            Some("date-time") => "DateTimeOffset".into(),
            Some("date") => "DateOnly".into(),
            Some("uuid") => "Guid".into(),
            Some("binary") | Some("byte") => "byte[]".into(),
            _ => "string".into(),
        },
        SchemaKind::Array { items } => format!("List<{}>", csharp_type(items, false)),
        SchemaKind::Object {
            additional_properties,
            ..
        } => match additional_properties {
            AdditionalProperties::Schema { value } => {
                format!("Dictionary<string, {}>", csharp_type(value, false))
            }
            _ => "JsonElement".into(),
        },
        SchemaKind::Reference { reference } => {
            pascal_case(reference.rsplit('/').next().unwrap_or(reference))
        }
        SchemaKind::OneOf { .. } | SchemaKind::AnyOf { .. } | SchemaKind::AllOf { .. } => {
            "JsonElement".into()
        }
    };
    nullable_type(
        base,
        optional || value.nullable || value.optional || value.nullish,
    )
}

fn nullable_type(base: String, nullable: bool) -> String {
    if !nullable {
        return base;
    }
    format!("{base}?")
}

fn is_reference_type(value: &SchemaValue) -> bool {
    !matches!(
        value.kind,
        SchemaKind::Boolean
            | SchemaKind::Integer
            | SchemaKind::Number
            | SchemaKind::Null
            | SchemaKind::Any
            | SchemaKind::Not { .. }
            | SchemaKind::OneOf { .. }
            | SchemaKind::AnyOf { .. }
            | SchemaKind::AllOf { .. }
    )
}

fn http_method_name(method: &str) -> &'static str {
    match method {
        "GET" => "Get",
        "POST" => "Post",
        "PUT" => "Put",
        "PATCH" => "Patch",
        "DELETE" => "Delete",
        _ => "Get",
    }
}

fn render_readme(
    api: &Api,
    package: &str,
    namespace: &str,
    client_style: SdkClientStyle,
) -> String {
    let style = if client_style == SdkClientStyle::Namespaced {
        "namespaced"
    } else {
        "flat"
    };
    let operation = api
        .operations
        .first()
        .map(|operation| pascal_case(&operation.id))
        .unwrap_or_else(|| "Operation".into());
    let resource = operation_groups(api)
        .first()
        .cloned()
        .unwrap_or_else(|| "Default".into());
    format!(
        "# {package}\n\nGenerated .NET 8 client for {}. This release selected the **{style}** client style.\n\n```csharp\nusing {namespace};\n\nvar client = new KajiClient(httpClient, new KajiClientOptions\n{{\n    BaseUrl = \"https://api.example.com\",\n    ApiKey = Environment.GetEnvironmentVariable(\"API_KEY\"),\n}});\n```\n\n## Flat client\n\n```csharp\nawait client.{operation}Async(/* typed arguments */);\n```\n\n## Namespaced client\n\n```csharp\nawait client.{resource}.{operation}Async(/* typed arguments */);\n```\n\nThe namespaced example applies to packages generated with `SdkClientStyle::Namespaced`; direct `KajiClient` methods remain available in that mode. See [STYLE_GUIDE.md](STYLE_GUIDE.md) for selection guidance.\n",
        api.name,
    )
}

fn render_style_guide(api: &Api, namespace: &str, client_style: SdkClientStyle) -> String {
    let operation = api
        .operations
        .first()
        .map(|operation| pascal_case(&operation.id))
        .unwrap_or_else(|| "Operation".into());
    let resource = operation_groups(api)
        .first()
        .cloned()
        .unwrap_or_else(|| "Default".into());
    let selected = match client_style {
        SdkClientStyle::Flat => "flat",
        SdkClientStyle::Namespaced => "namespaced",
    };
    format!(
        "# .NET SDK style guide\n\nThis generated package selected the **{selected}** client layout. Both layouts retain the same models, authentication options, cancellation support, and typed return values.\n\n## Flat\n\nUse the direct operation methods when a compact client is preferable.\n\n```csharp\nusing {namespace};\n\nvar client = new KajiClient(httpClient, options);\nawait client.{operation}Async(/* typed arguments */);\n```\n\n## Namespaced\n\nUse resource properties to make a larger API easier to navigate. Kaji uses the first OpenAPI tag; if none is present, it derives the first useful path segment while skipping `v#`, `api`, and `email`.\n\n```csharp\nusing {namespace};\n\nvar client = new KajiClient(httpClient, options);\nawait client.{resource}.{operation}Async(/* typed arguments */);\n```\n\n## Media and streaming\n\nNon-JSON success responses are returned as `byte[]`; non-JSON request bodies accept `byte[]`. A `text/event-stream` operation returns `IAsyncEnumerable<string>` containing event data lines.\n\nSelect the layout during generation with `SdkClientStyle::Flat` or `SdkClientStyle::Namespaced`. The original direct `KajiClient` methods remain available when the namespaced façade is selected.\n"
    )
}

fn pascal_case(value: &str) -> String {
    let words = identifier_words(value);
    let mut output = words
        .into_iter()
        .map(|word| {
            let mut characters = word.chars();
            characters
                .next()
                .map(|first| first.to_ascii_uppercase().to_string() + characters.as_str())
                .unwrap_or_default()
        })
        .collect::<String>();
    if output.is_empty() {
        output = "GeneratedValue".into();
    }
    if output.as_bytes().first().is_some_and(u8::is_ascii_digit) {
        output.insert(0, 'V');
    }
    if csharp_keyword(&output) {
        output.push_str("Value");
    }
    output
}

fn camel_case(value: &str) -> String {
    let mut output = pascal_case(value);
    if let Some(first) = output.get_mut(0..1) {
        first.make_ascii_lowercase();
    }
    if csharp_keyword(&output) {
        format!("@{output}")
    } else {
        output
    }
}

fn kebab_case(value: &str) -> String {
    identifier_words(value)
        .into_iter()
        .map(|word| word.to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join("-")
}

fn dotnet_namespace(package: &str) -> String {
    let value = pascal_case(package);
    format!("Kaji.{value}")
}

fn identifier_words(value: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut current = String::new();
    for character in value.chars() {
        if character.is_ascii_alphanumeric() {
            if character.is_ascii_uppercase()
                && !current.is_empty()
                && current
                    .chars()
                    .last()
                    .is_some_and(|last| last.is_ascii_lowercase())
            {
                words.push(std::mem::take(&mut current));
            }
            current.push(character);
        } else if !current.is_empty() {
            words.push(std::mem::take(&mut current));
        }
    }
    if !current.is_empty() {
        words.push(current);
    }
    words
}

fn enum_member_name(value: &str, index: usize) -> String {
    let name = pascal_case(value);
    if name == "GeneratedValue" {
        format!("Value{index}")
    } else {
        name
    }
}

fn csharp_keyword(value: &str) -> bool {
    matches!(
        value.to_ascii_lowercase().as_str(),
        "abstract"
            | "as"
            | "base"
            | "bool"
            | "break"
            | "byte"
            | "case"
            | "catch"
            | "char"
            | "class"
            | "const"
            | "continue"
            | "decimal"
            | "default"
            | "delegate"
            | "do"
            | "double"
            | "else"
            | "enum"
            | "event"
            | "explicit"
            | "extern"
            | "false"
            | "finally"
            | "fixed"
            | "float"
            | "for"
            | "foreach"
            | "goto"
            | "if"
            | "implicit"
            | "in"
            | "int"
            | "interface"
            | "internal"
            | "is"
            | "lock"
            | "long"
            | "namespace"
            | "new"
            | "null"
            | "object"
            | "operator"
            | "out"
            | "override"
            | "params"
            | "private"
            | "protected"
            | "public"
            | "readonly"
            | "ref"
            | "return"
            | "sbyte"
            | "sealed"
            | "short"
            | "sizeof"
            | "stackalloc"
            | "static"
            | "string"
            | "struct"
            | "switch"
            | "this"
            | "throw"
            | "true"
            | "try"
            | "typeof"
            | "uint"
            | "ulong"
            | "unchecked"
            | "unsafe"
            | "ushort"
            | "using"
            | "virtual"
            | "void"
            | "volatile"
            | "while"
    )
}

fn dotnet_version(version: &str) -> String {
    let segments = version.split('-').collect::<Vec<_>>();
    if segments.len() == 3 && segments.iter().all(|part| part.parse::<u64>().is_ok()) {
        return segments.join(".");
    }
    if version.split('.').count() == 3 && version.split('.').all(|part| part.parse::<u64>().is_ok())
    {
        return version.into();
    }
    "0.1.0".into()
}

fn xml_escape(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeMap;

    use kaji_core::{
        Field, HttpMethod, OperationMediaType, OperationParameter, OperationRequestBody, Schema,
    };

    use super::*;

    fn api() -> Api {
        Api {
            name: "Example API".into(),
            version: "2026-09-19".into(),
            schemas: vec![Schema::new(
                "Contact",
                SchemaValue::new(SchemaKind::Object {
                    fields: vec![
                        Field {
                            name: "email".into(),
                            value: SchemaValue::new(SchemaKind::String),
                            required: true,
                            annotations: BTreeMap::new(),
                        },
                        Field {
                            name: "display-name".into(),
                            value: SchemaValue::new(SchemaKind::String),
                            required: false,
                            annotations: BTreeMap::new(),
                        },
                    ],
                    additional_properties: AdditionalProperties::Forbidden,
                }),
            )],
            operations: vec![
                Operation {
                    id: "getContact".into(),
                    method: HttpMethod::Get,
                    path: "/contacts/{contactId}".into(),
                    response_type: "Contact".into(),
                    request_type: None,
                    parameters: vec![
                        OperationParameter {
                            name: "contactId".into(),
                            location: "path".into(),
                            required: true,
                            schema: Some(SchemaValue::new(SchemaKind::String)),
                            description: None,
                            annotations: BTreeMap::new(),
                        },
                        OperationParameter {
                            name: "includeDeleted".into(),
                            location: "query".into(),
                            required: false,
                            schema: Some(SchemaValue::new(SchemaKind::Boolean)),
                            description: None,
                            annotations: BTreeMap::new(),
                        },
                    ],
                    request_body: None,
                    responses: vec![],
                    security: vec![],
                    annotations: BTreeMap::new(),
                },
                Operation {
                    id: "createContact".into(),
                    method: HttpMethod::Post,
                    path: "/contacts".into(),
                    response_type: "Contact".into(),
                    request_type: None,
                    parameters: vec![OperationParameter {
                        name: "dryRun".into(),
                        location: "query".into(),
                        required: false,
                        schema: Some(SchemaValue::new(SchemaKind::Boolean)),
                        description: None,
                        annotations: BTreeMap::new(),
                    }],
                    request_body: Some(OperationRequestBody {
                        required: true,
                        description: None,
                        media_types: vec![OperationMediaType {
                            content_type: "application/json".into(),
                            schema: Some(SchemaValue::reference("#/components/schemas/Contact")),
                        }],
                    }),
                    responses: vec![],
                    security: vec![],
                    annotations: BTreeMap::new(),
                },
            ],
            annotations: BTreeMap::new(),
        }
    }

    #[test]
    fn generates_a_deterministic_dotnet_package() {
        let first = generate_dotnet_sdk(&api(), "sdk/dotnet", Some("example-api-sdk")).unwrap();
        let second = generate_dotnet_sdk(&api(), "sdk/dotnet", Some("example-api-sdk")).unwrap();
        assert_eq!(first, second);
        assert!(
            first
                .get("sdk/dotnet/ExampleApiSdk.csproj")
                .unwrap()
                .contains("<TargetFramework>net8.0</TargetFramework>")
        );
        assert!(
            first
                .get("sdk/dotnet/Models.cs")
                .unwrap()
                .contains("public sealed record Contact")
        );
        let client = first.get("sdk/dotnet/KajiClient.cs").unwrap();
        assert!(client.contains(
            "Task<Contact> GetContactAsync(string contactId, bool? includeDeleted = default"
        ));
        assert!(client.contains("Uri.EscapeDataString(ParameterString(contactId))"));
        assert!(client.contains("JsonContent.Create(body, options: JsonOptions)"));
        assert!(client.contains("CreateContactAsync(Contact body, bool? dryRun = default"));
        assert!(client.contains("ApiKeyHeader"));
        assert!(client.contains("KajiRetryOptions"));
        assert!(client.contains("SendWithRetryAsync"));
        assert!(client.contains("Idempotency-Key"));
        assert!(client.contains("IKajiClientHooks"));
    }

    #[test]
    fn rejects_empty_or_unsafe_output_directory() {
        assert!(generate_dotnet_sdk(&api(), "/", None).is_err());
        assert!(generate_dotnet_sdk(&api(), "sdk/../dotnet", None).is_err());
    }

    #[test]
    fn namespaced_style_exports_typed_resource_facades() {
        let mut tagged = api();
        tagged.operations[0]
            .annotations
            .insert("tags".into(), serde_json::json!(["People"]));
        let tree = generate_dotnet_sdk_with_style(
            &tagged,
            "sdk/dotnet",
            Some("example-api-sdk"),
            SdkClientStyle::Namespaced,
        )
        .unwrap();

        let client = tree.get("sdk/dotnet/KajiClient.cs").unwrap();
        assert!(client.contains("public PeopleResource People { get; }"));
        assert!(client.contains("People = new PeopleResource(this);"));
        assert!(client.contains("public ContactsResource Contacts { get; }"));

        let resources = tree.get("sdk/dotnet/Resources.cs").unwrap();
        assert!(resources.contains("public sealed class PeopleResource"));
        assert!(resources.contains("Task<Contact> GetContactAsync(string contactId"));
        assert!(
            resources
                .contains("_client.GetContactAsync(contactId, includeDeleted, cancellationToken)")
        );
        assert!(
            tree.get("sdk/dotnet/STYLE_GUIDE.md")
                .unwrap()
                .contains("## Namespaced")
        );

        let flat = generate_dotnet_sdk(&api(), "sdk/dotnet", None).unwrap();
        assert!(flat.get("sdk/dotnet/Resources.cs").is_none());
    }

    #[test]
    fn emits_binary_upload_download_and_sse_surfaces() {
        let mut source = api();
        source.operations[0].id = "downloadContact".into();
        source.operations[0].request_body = Some(OperationRequestBody {
            required: true,
            description: None,
            media_types: vec![OperationMediaType {
                content_type: "application/octet-stream".into(),
                schema: Some(SchemaValue::new(SchemaKind::String)),
            }],
        });
        source.operations[0].responses = vec![kaji_core::OperationResponse {
            status: "200".into(),
            description: None,
            media_types: vec![OperationMediaType {
                content_type: "application/pdf".into(),
                schema: None,
            }],
        }];
        let mut stream = source.operations[0].clone();
        stream.id = "watchContacts".into();
        stream.request_body = None;
        stream.responses[0].media_types[0].content_type = "text/event-stream".into();
        source.operations.push(stream);
        let tree = generate_dotnet_sdk(&source, "sdk/dotnet", None).unwrap();
        let client = tree.get("sdk/dotnet/KajiClient.cs").unwrap();
        assert!(client.contains("Task<byte[]> DownloadContactAsync"));
        assert!(client.contains("ByteArrayContent(body)"));
        assert!(client.contains("SendBytesAsync"));
        assert!(client.contains("IAsyncEnumerable<string> WatchContactsAsync"));
        assert!(client.contains("StreamSseAsync"));
    }

    #[test]
    fn emits_operation_status_errors_with_declared_bodies() {
        let mut source = api();
        source.operations[0]
            .responses
            .push(kaji_core::OperationResponse {
                status: "404".into(),
                description: None,
                media_types: vec![OperationMediaType {
                    content_type: "application/json".into(),
                    schema: Some(SchemaValue::reference("#/components/schemas/Contact")),
                }],
            });
        let tree = generate_dotnet_sdk(&source, "sdk/dotnet", None).unwrap();
        let errors = tree.get("sdk/dotnet/ApiException.cs").unwrap();
        let client = tree.get("sdk/dotnet/KajiClient.cs").unwrap();
        assert!(errors.contains("class GetContactStatus404Exception : ApiException"));
        assert!(errors.contains("Contact? Body"));
        assert!(client.contains("throw MapGetContactError(error)"));
        assert!(client.contains("TryDeserializeError<Contact>(error.ResponseBody)"));
    }
}
